// Build messages array for Claude via OpenRouter
const input = $input.first().json;
const history = input.conversationHistory || [];
const sessionData = input.sessionData || {};
const currentState = input.currentState || 'classifying';

// System prompt for Med Africa
const systemPrompt = `أنت وكيل دعم عملاء لشركة Med Africa، شركة مغربية متخصصة في توصيل منتجات Temu للمغرب.

قواعد الأسلوب:
- تكلم دائما بالدارجة المغربية بأسلوب محترم ودافئ
- استعمل كلمات مثل: "واش"، "بغيت"، "غادي"، "ديال"، "مزيان"، "عافاك"
- ابدأ دائما بـ "أهلاً" أو "لاباس" أو "مرحبا"
- كن موجزاً — جملتان أو ثلاثة في كل رد
- إذا كتب العميل بالعربية الفصحى أو الفرنسية، رد بنفس اللغة مع الدارجة

مراحل جمع البيانات (اتبع الترتيب):
1. اسأل عن الاسم الكامل
2. اسأل عن اللقب (نسب)
3. اسأل عن المدينة
4. اسأل عن رقم التتبع (numéro de suivi)
5. اسأل: "شنو المشكل أو الاستفسار ديالك؟"

تصنيف الطلب — حدد نوعاً واحداً فقط:
شكاوي:
  - "تأخير": الطرد تأخر عن الموعد المحدد
  - "ضياع": الطرد ما وصلش خالص
  - "تلف": الطرد وصل مكسور أو ناقص
  - "منتج_خطأ": وصل منتج مختلف على اللي طلبه

استفسارات:
  - "تتبع": يبغي يعرف فين الطرد دابا
  - "إرجاع": يبغي يرجع المنتج
  - "توصيل": يبغي يعرف عن مواعيد التوصيل
  - "عام": أي سؤال آخر

تحديد الأولوية:
  - "عاجل": ضياع + مضى أكثر من 30 يوم، أو تلف كلي
  - "مهم": تأخير + مضى أكثر من 15 يوم، أو منتج خطأ
  - "عادي": باقي الحالات

بيانات العميل المتوفرة حالياً:
- الاسم: ${sessionData.firstName || 'غير متوفر'}
- اللقب: ${sessionData.lastName || 'غير متوفر'}
- المدينة: ${sessionData.city || 'غير متوفر'}
- رقم التتبع: ${sessionData.trackingNumber || 'غير متوفر'}

الحالة الحالية: ${currentState}

في آخر كل محادثة مكتملة، أرجع JSON بهذا الشكل:
{
  "reply": "نص الرد للعميل",
  "type": "شكوى|استفسار",
  "category": "تأخير|ضياع|تلف|منتج_خطأ|تتبع|إرجاع|توصيل|عام",
  "priority": "عاجل|مهم|عادي",
  "summary": "ملخص قصير بالعربية",
  "data_complete": true|false
}

يجب أن ترجع دائما الجواب بصيغة JSON فقط، بلا أي نص إضافي.`;

// Build messages array from conversation history
const messages = history.map(msg => ({
  role: msg.role === 'user' ? 'user' : 'assistant',
  content: msg.content
}));

// If the latest message isn't from the user, add it
if (input.messageBody && (messages.length === 0 || messages[messages.length - 1].content !== input.messageBody)) {
  messages.push({
    role: 'user',
    content: input.messageBody
  });
}

return [{
  json: {
    systemPrompt,
    messages,
    phoneNumber: input.phoneNumber,
    sessionData,
    currentState
  }
}];

// Parse Claude response from OpenRouter
const input = $input.first().json;
const phoneNumber = $('Build AI Prompt').first().json.phoneNumber;
const sessionData = $('Build AI Prompt').first().json.sessionData;

let aiResponse;

try {
  // OpenRouter returns response in choices[0].message.content
  const body = input.body || input;
  const content = body.choices?.[0]?.message?.content || '';

  // Try to parse as JSON
  try {
    aiResponse = JSON.parse(content);
  } catch (e) {
    // Try to extract JSON from the response
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      aiResponse = JSON.parse(jsonMatch[0]);
    } else {
      // Fallback: treat entire content as reply
      aiResponse = {
        reply: content,
        type: 'استفسار',
        category: 'عام',
        priority: 'عادي',
        summary: '',
        data_complete: false
      };
    }
  }
} catch (error) {
  aiResponse = {
    reply: 'عذراً، وقع مشكل تقني. عافاك عاود حاول من بعد.',
    type: 'استفسار',
    category: 'عام',
    priority: 'عادي',
    summary: 'خطأ تقني',
    data_complete: false
  };
}

// Ensure all required fields exist
const result = {
  phoneNumber,
  sessionData,
  aiResponse: {
    reply: aiResponse.reply || '',
    type: aiResponse.type || 'استفسار',
    category: aiResponse.category || 'عام',
    priority: aiResponse.priority || 'عادي',
    summary: aiResponse.summary || '',
    data_complete: aiResponse.data_complete || false
  },
  reply: aiResponse.reply || '',
  reply_text: aiResponse.reply || '',
  type: aiResponse.type || 'استفسار',
  category: aiResponse.category || 'عام',
  priority: aiResponse.priority || 'عادي',
  summary: aiResponse.summary || '',
  data_complete: aiResponse.data_complete || false
};

return [{ json: result }];
